"""Writes ../shapes/tri_<v>.txt, the shape file of the family member v (H the subgroup of order k of Z_v*, generated by g^e), for ../qskew; prints v, k, e, g, the generator and the number of orbits.
usage: python3 mk_shape.py v k"""
import sys, os, json
HERE=os.path.dirname(os.path.abspath(__file__)); sys.path.insert(0, os.path.join(HERE,'..'))      # ../qdrv.py
from qdrv import shape
from sympy import primitive_root
v=int(sys.argv[1]); k=int(sys.argv[2])
g=primitive_root(v); e=(v-1)//k
gens=[pow(g,e,v)]
os.makedirs(os.path.join(HERE,"..","shapes"),exist_ok=True)
d=shape(v,gens,os.path.join(HERE,"..","shapes",f"tri_{v}.txt"))
print(v,k,e,'g',g,'gens',gens,'n',d['n'])
